The DHT22 is a popular temperature and humidity sensor that is widely used in various IoT projects. Calibration of DHT22 sensor is a process of adjusting its parameters to match the actual ambient temperature and humidity conditions.

Here is an example code for DHT22 sensor calibration in Python using the RPi.GPIO library:
```python
import RPi.GPIO as GPIO
import dht22
import time

# Set up GPIO pins for DHT22
DHT22_PIN = 4  # GPIO pin 4 is used for DHT22 data pin

# Set up DHT22 sensor object
dht22_sensor = dht22.DHT22(pin=DHT22_PIN)

# Calibration function
def calibrate_dht22():
    # Initialize variables
    temp_cal = 0
    hum_cal = 0
    count = 0

    # Read DHT22 sensor data 100 times
    for i in range(100):
        # Read temperature and humidity data from DHT22
        temp, hum = dht22_sensor.read()
        temp_cal += temp
        hum_cal += hum
        count += 1
        time.sleep(0.1)

    # Calculate average temperature and humidity
    temp_cal_avg = temp_cal / count
    hum_cal_avg = hum_cal / count

    # Print calibration results
    print("Calibration Results:")
    print("Temperature offset: {:.2f}°C".format(temp_cal_avg))
    print("Humidity offset: {:.2f}%".format(hum_cal_avg))

    # Update DHT22 sensor object with calibration results
    dht22_sensor.temp_offset = temp_cal_avg
    dht22_sensor.hum_offset = hum_cal_avg

# Main program
if __name__ == "__main__":
    # Initialize GPIO library
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT22_PIN, GPIO.IN)

    # Calibrate DHT22 sensor
    calibrate_dht22()

    # Read DHT22 sensor data after calibration
    temp, hum = dht22_sensor.read()
    print("Temperature: {:.2f}°C".format(temp))
    print("Humidity: {:.2f}%".format(hum))
```
