#include <pigpio.h>

#define PIN 12 // GPIO pin 12

int main() {
  // Initialize the pigpio library
  if (piInit() < 0) {
    std::cerr << "pigpio initialization failed" << std::endl;
    return 1;
  }

  // Set the mode of the GPIO pin
  pinMode(PIN, PWM_OUTPUT);

  // Set the default state of the pin
  gpioWrite(PIN, 0);

  while (true) {
    // Toggle the pin state every 0.5 seconds
    gpioWrite(PIN, 1);
    delay(500000);
    gpioWrite(PIN, 0);
    delay(500000);
  }

  // Clean up
  piShutdown();

  return 0;
}
